import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import AccueilPage from './pages/accueilpage.jsx';
import ChambrePage from './pages/chambrepage.jsx';
import EtablissementPage from './pages/etablissementpage.jsx';
import EtudiantPage from './pages/etudiantpage.jsx';
import LoginPage from './pages/loginpage.jsx';
import ReservationPage from './pages/reservationpage.jsx';
import ForgotPasswordPage from './pages/forgotPassword.jsx';
import ResetPasswordPage from './pages/resetPassword.jsx';
import { isAuthenticated } from './utils/authService';

// Composant pour protéger les routes qui nécessitent une authentification
const ProtectedRoute = ({ element }) => {
  return isAuthenticated() ? element : <Navigate to="/login" />;
};

function Approute() {
  return (
    <Routes>
      <Route path="/" element={<AccueilPage />} />
      <Route path="/chambres" element={<ProtectedRoute element={<ChambrePage />} />} />
      <Route path="/etablissements" element={<ProtectedRoute element={<EtablissementPage />} />} />
      <Route path="/etudiants" element={<ProtectedRoute element={<EtudiantPage />} />} />
      <Route path="/login" element={<LoginPage />} />
      <Route path="/reservations" element={<ProtectedRoute element={<ReservationPage />} />} />
      <Route path="/forgot-password" element={<ForgotPasswordPage />} />
      <Route path="/reset-password/:token" element={<ResetPasswordPage />} />
    </Routes>
  );
}

export default Approute;
